\u0442 \u043a\u043e\u0434\u0430, \u043d\u0435\u0442 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u043e\u0432, \u043d\u0435\u0442 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e\u0439 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u0438.\n- task.json: question \u043f\u0440\u043e CAMUV; context: \"Design an experiment... Do not claim that an experiment was run\"; documents.track.md = \u043e\u0434\u043d\u0430 \u0441\u0442\u0440\u043e\u043a\u0430: \"Design-only task; repositories and compute are not required.\"\n- Environment (\u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u043e \u043a\u043e\u043c\u0430\u043d\u0434\u0430\u043c\u0438): Python 3.14.4; \u0441\u0435\u0442\u044c \u041e\u0422\u041a\u041b\u042e\u0427\u0415\u041d\u0410; numpy/scipy/pandas/causal-learn/PyTorch \u041d\u0415 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u044b; GPU \u043e\u0442\u043a\u043b\u044e\u0447\u0451\u043d; 224 CPU-\u044f\u0434\u0440\u0430 (affinity); datasets: [].\n- \u0412\u044b\u0432\u043e\u0434: \u043a\u043e\u0434\u0430 CAMUV, \u0441\u0442\u0430\u0442\u044c\u0438 \u043f\u043e CAMUV \u0438 \u043a\u0430\u043a\u0438\u0445-\u043b\u0438\u0431\u043e \u0434\u0430\u043d\u043d\u044b\u0445 \u0432 workspace \u043d\u0435\u0442. \u0414\u0438\u0437\u0430\u0439\u043d \u0441\u0442\u0440\u043e\u0438\u0442\u0441\u044f \u00ab\u043d\u0430 \u0431\u0443\u043c\u0430\u0433\u0435\u00bb; \u0432\u0441\u0451 CAMUV-\u0441\u043f\u0435\u0446\u0438\u0444\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u0431\u0435\u0440\u0451\u043c \u043b\u0438\u0431\u043e \u0438\u0437 \u0442\u0432\u043e\u0438\u0445 \u0443\u0442\u043e\u0447\u043d\u0435\u043d\u0438\u0439, \u043b\u0438\u0431\u043e \u044f\u0432\u043d\u043e \u043f\u043e\u043c\u0435\u0447\u0430\u0435\u043c \u043a\u0430\u043a \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435.\n\n== 2. \u041f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u043d\u044b\u0439 \u043f\u043e\u0434\u0445\u043e\u0434 \u043a \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0443 (\u0441\u043a\u0435\u043b\u0435\u0442) ==\n\u041e\u0431\u044a\u0435\u043a\u0442 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438: CAMUV \u043d\u0430 \u043b\u0438\u043d\u0435\u0439\u043d\u044b\u0445 SEM-\u0434\u0430\u043d\u043d\u044b\u0445 \u0441 \u043d\u0435\u0437\u0430\u043c\u0435\u0442\u043d\u044b\u043c\u0438 \u043e\u0431\u0449\u0438\u043c\u0438 \u043f\u0440\u0438\u0447\u0438\u043d\u0430\u043c\u0438. \u041f\u043e\u0441\u043a\u043e\u043b\u044c\u043a\u0443 \u043b\u0430\u0442\u0435\u043d\u0442\u044b \u043d\u0435\u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b, ground-truth \u0434\u043b\u044f \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f \u2014 \u043d\u0435 \u0438\u0441\u0445\u043e\u0434\u043d\u044b\u0439 DAG, \u0430 \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0433\u0440\u0430\u0444: \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0435 \u0440\u0451\u0431\u0440\u0430 \u043c\u0435\u0436\u0434\u0443 \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u043c\u0438 + \u0434\u0432\u0443\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0435 \u0440\u0451\u0431\u0440\u0430 (= \u043f\u0430\u0440\u044b \u0441 \u043e\u0431\u0449\u0438\u043c \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u043c \u043f\u0440\u0435\u0434\u043a\u043e\u043c).\n\n\u0414\u0430\u043d\u043d\u044b\u0435:\nA) \u0421\u0438\u043d\u0442\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440 (\u043e\u0441\u043d\u043e\u0432\u043d\u0430\u044f \u0447\u0430\u0441\u0442\u044c): DAG-\u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440 (n \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u0445 \u2208 {10, 20, 50}, sweep \u043f\u043e \u043f\u043b\u043e\u0442\u043d\u043e\u0441\u0442\u0438 \u0440\u0451\u0431\u0435\u0440), \u0447\u0438\u0441\u043b\u043e \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u0445 \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0435\u0440\u043e\u0432 L \u2208 {0, 1, 2, 3}, \u043a\u0430\u0436\u0434\u044b\u0439 \u043b\u0430\u0442\u0435\u043d\u0442 \u2014 \u043e\u0431\u0449\u0438\u0439 \u043f\u0440\u0435\u0434\u043e\u043a \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0430 \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u0445 (sweep \u0434\u043e\u043b\u0438 \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u043d\u0433\u0430), \u041d\u0415\u0413\u0410\u0423\u0421\u0421\u041e\u0412\u042b\u0419 \u0448\u0443\u043c (Laplace / exp-Gaussian / \u0441\u043a\u043e\u0448\u0435\u043d\u043d\u044b\u0439), \u043e\u0431\u044a\u0451\u043c\u044b \u0432\u044b\u0431\u043e\u0440\u043a\u0438 \u2208 {500, 2000, 10000}, \u2265100 \u0440\u0435\u043f\u043b\u0438\u043a \u043d\u0430 \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044e, \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0441\u0438\u0434\u044b.\nB) \u0420\u0435\u0430\u043b\u044c\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 (\u0432\u0442\u043e\u0440\u0438\u0447\u043d\u0430\u044f \u0447\u0430\u0441\u0442\u044c): Sachs (111\u00d711, \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0439 \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a \u0441 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u043c PAG \u0432 \u043b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u0435); \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e \u0435\u0449\u0451 \u043e\u0434\u0438\u043d \u043d\u0430\u0431\u043e\u0440 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, insulin) \u2014 \u0443\u0442\u043e\u0447\u043d\u0438\u043c.\n\n\u0411\u0430\u0437\u043b\u0430\u0439\u043d\u044b:\n- FCMP (f-cMVP) \u2014 latent-aware, \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0442;\n- LiNGAM (\u0431\u0435\u0437 \u043b\u0430\u0442\u0435\u043d\u0442\u043e\u0432) \u2014 \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u043e \u043f\u0440\u043e\u0432\u0430\u043b\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u043f\u0440\u0438 \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u043d\u0433\u0435, \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u0446\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u043c\u043e\u0434\u0435\u043b\u0438 \u0441 \u043b\u0430\u0442\u0435\u043d\u0442\u0430\u043c\u0438;\n- ICU-LiNGAM (LiNGAM-\u0432\u0430\u0440\u0438\u0430\u043d\u0442 \u0441 latent confounders) \u2014 \u043f\u0440\u044f\u043c\u043e\u0439 \u0430\u043d\u0430\u043b\u043e\u0433;\n- \u0421\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0439 \u043e\u0440\u0438\u0435\u043d\u0442\u0430\u0442\u043e\u0440: \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0439 DAG \u0442\u043e\u0439 \u0436\u0435 \u043f\u043b\u043e\u0442\u043d\u043e\u0441\u0442\u0438 + \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0439 \u0433\u0440\u0430\u0444 \u0441 \u0442\u0435\u043c \u0436\u0435 \u0447\u0438\u0441\u043b\u043e\u043c \u0434\u0432\u0443\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0445 \u0440\u0451\u0431\u0435\u0440 (\u043d\u0438\u0436\u043d\u044f\u044f \u0433\u0440\u0430\u043d\u0438\u0446\u0430).\n\n\u041a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u043d\u044b\u0435 \u0443\u0441\u043b\u043e\u0432\u0438\u044f (controls):\nC1) L=0 (\u0431\u0435\u0437 \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0435\u0440\u043e\u0432) \u2014 \u00ab\u0430\u043d\u0442\u0438\u0433\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0439\u00bb \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c: CAMUV \u043e\u0431\u044f\u0437\u0430\u043d \u043d\u0435 \u0432\u044b\u0434\u0430\u0432\u0430\u0442\u044c \u0434\u0432\u0443\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0445 \u0440\u0451\u0431\u0435\u0440; \u043b\u043e\u0436\u043d\u0430\u044f \u0434\u043e\u043b\u044f bidirected \u2248 0.\nC2) \u0413\u0430\u0443\u0441\u0441\u043e\u0432\u044b\u0439 \u0448\u0443\u043c \u2014 \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0434\u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u043e \u043d\u0435\u0433\u0430\u0443\u0441\u0441\u043e\u0432\u043e\u0441\u0442\u0438: \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0438\u0440\u0443\u0435\u043c \u0433\u0440\u0430\u043d\u0438\u0446\u0443 \u043f\u0440\u0438\u043c\u0435\u043d\u0438\u043c\u043e\u0441\u0442\u0438 (\u043c\u0435\u0442\u043e\u0434 \u0434\u043e\u043b\u0436\u0435\u043d \u0434\u0435\u0433\u0440\u0430\u0434\u0438\u0440\u043e\u0432\u0430\u0442\u044c).\nC3) (\u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e) \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u0435 \u043a\u043e\u043b\u043b\u0430\u0439\u0434\u0435\u0440\u044b, \u0435\u0441\u043b\u0438 \u043c\u043e\u0434\u0435\u043b\u044c CAMUV \u0438\u0445 \u043d\u0435 \u0434\u043e\u043f\u0443\u0441\u043a\u0430\u0435\u0442 \u2014 \u0437\u043e\u043d\u0434 \u0440\u043e\u0431\u0430\u0441\u0442\u043d\u043e\u0441\u0442\u0438.\n\n\u041c\u0435\u0442\u0440\u0438\u043a\u0438: SHD \u0438 edge-level precision/recall/F1 \u043f\u043e (\u0430) \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u043c, (\u0431) \u0434\u0432\u0443\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u043c \u0440\u0451\u0431\u0440\u0430\u043c \u043f\u0440\u043e\u0442\u0438\u0432 ground-truth \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0433\u043e \u0433\u0440\u0430\u0444\u0430; false-bidirected rate \u0432 C1; runtime \u043d\u0430 \u0438\u043d\u0441\u0442\u0430\u043d\u0441.\n\u0421\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430: \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u043e \u0440\u0435\u043f\u043b\u0438\u043a\u0430\u043c (bootstrap CI / \u043f\u0430\u0440\u043d\u044b\u0435 \u0442\u0435\u0441\u0442\u044b), \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0441\u0438\u0434\u044b.\n\u0413\u0438\u043f\u043e\u0442\u0435\u0437\u044b: H1 \u2014 CAMUV \u2265 FCMP/ICU-LiNGAM \u043f\u043e F1/SHD \u043f\u0440\u0438 \u0441\u043e\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u0438 \u043f\u0440\u0435\u0434\u043f\u043e\u0441\u044b\u043b\u043e\u043a; H2 \u2014 \u22480 \u043b\u043e\u0436\u043d\u044b\u0445 bidirected \u043f\u0440\u0438 L=0; H3 \u2014 \u043d\u0430 Sachs \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u0441\u043e\u0433\u043b\u0430\u0441\u0443\u0435\u0442\u0441\u044f \u0441 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u043c PAG (\u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u0430\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430, n=111 \u043c\u0430\u043b).\n\n== 3. \u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f vs \u0444\u0430\u043a\u0442\u044b (\u044f\u0432\u043d\u0430\u044f \u043c\u0430\u0440\u043a\u0438\u0440\u043e\u0432\u043a\u0430) ==\n\u0424\u0410\u041a\u0422\u042b (\u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u043e \u043c\u043d\u043e\u0439 \u0432 \u044d\u0442\u043e\u0439 \u0441\u0440\u0435\u0434\u0435): \u043f\u0443\u0441\u0442\u043e-\u043a\u0440\u043e\u043c\u0435-task.json workspace; \u0441\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430; scientific-\u0441\u0442\u0435\u043a \u043d\u0435 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d; GPU \u043d\u0435\u0442; task.json \u0437\u0430\u043f\u0440\u0435\u0449\u0430\u0435\u0442 \u0437\u0430\u044f\u0432\u043b\u044f\u0442\u044c \u043e \u043f\u0440\u043e\u0432\u0435\u0434\u0451\u043d\u043d\u043e\u043c \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0435.\n\u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u042f (\u043c\u043e\u0438 \u0434\u043e\u0433\u0430\u0434\u043a\u0438 \u2014 \u0441\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430, \u043a \u0441\u0442\u0430\u0442\u044c\u0435 CAMUV \u043d\u0435\u0442 \u0434\u043e\u0441\u0442\u0443\u043f\u0430, \u041d\u0415 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u043e):\n- \u041c\u043e\u0434\u0435\u043b\u044c CAMUV: \u043b\u0438\u043d\u0435\u0439\u043d\u044b\u0435 SEM, \u043d\u0435\u0433\u0430\u0443\u0441\u0441\u043e\u0432\u044b\u0439 \u0448\u0443\u043c, \u043b\u0430\u0442\u0435\u043d\u0442\u044b \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u043e\u0431\u0449\u0438\u0435 \u043f\u0440\u0438\u0447\u0438\u043d\u044b \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u0445 \u043f\u0430\u0440, \u043c\u0430\u043b\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u043b\u0430\u0442\u0435\u043d\u0442\u043e\u0432, \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u0445 \u043a\u043e\u043b\u043b\u0430\u0439\u0434\u0435\u0440\u043e\u0432 \u043d\u0435\u0442, \u043f\u0440\u044f\u043c\u044b\u0445 \u043b\u0430\u0442\u0435\u043d\u0442\u2192\u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u043e \u0441\u0432\u044f\u0437\u0435\u0439 \u0441\u0432\u0435\u0440\u0445 \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u043d\u0433\u0430 \u043d\u0435\u0442. [\u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u0415]\n- \u0412\u044b\u0445\u043e\u0434 CAMUV \u2014 \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0433\u0440\u0430\u0444 \u0441 \u0434\u0432\u0443\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u043c\u0438 \u0440\u0451\u0431\u0440\u0430\u043c\u0438 (\u043d\u0435 \u044f\u0432\u043d\u044b\u0435 \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u0435 \u0443\u0437\u043b\u044b). [\u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u0415]\n- \u041f\u0443\u0431\u043b\u0438\u0447\u043d\u0430\u044f \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f CAMUV \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u0435\u0442 (\u0438\u043d\u0430\u0447\u0435 \u043d\u0443\u0436\u0435\u043d \u0440\u0435\u0438\u043c\u043f\u043b\u0435\u043c\u0435\u043d\u0442 \u043f\u043e \u0441\u0442\u0430\u0442\u044c\u0435 \u2014 \u044d\u0442\u043e \u043c\u0435\u043d\u044f\u0435\u0442 \u0440\u0438\u0441\u043a \u0438 \u043f\u043b\u0430\u043d). [\u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u0415]\n- \u0411\u0430\u0437\u043b\u0430\u0439\u043d\u044b \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b: FCMP/LiNGAM \u0432 causal-learn, ICU-LiNGAM \u2014 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u0439 \u043a\u043e\u0434. [\u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u0415]\n- Sachs \u0441\u043a\u0430\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0432 \u043c\u043e\u043c\u0435\u043d\u0442 \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430 (111\u00d711, \u043c\u0430\u043b\u044b\u0439). [\u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u0415]\n- \u0411\u044e\u0434\u0436\u0435\u0442: \u043d\u0435 \u0437\u0430\u0434\u0430\u043d; \u043f\u0440\u0435\u0434\u043f\u043e\u043b\u0430\u0433\u0430\u044e \u0447\u0430\u0441\u044b CPU-\u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u043d\u0430 224 \u044f\u0434\u0440\u0430\u0445, GPU \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d (\u0432\u0430\u0436\u043d\u043e, \u0435\u0441\u043b\u0438 CAMUV \u0433\u0440\u0430\u0434\u0438\u0435\u043d\u0442\u043d\u044b\u0439/\u043d\u0435\u0439\u0440\u043e\u0441\u0435\u0442\u0435\u0432\u043e\u0439). [\u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u0415]\n\u041d\u0415\u041e\u041f\u0420\u0415\u0414\u0415\u041b\u0401\u041d\u041d\u041e\u0421\u0422\u0418: \u0442\u043e\u0447\u043d\u044b\u0435 \u0443\u0441\u043b\u043e\u0432\u0438\u044f \u0438\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u0435\u043c\u043e\u0441\u0442\u0438 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435 \u043d\u0430 \u0447\u0438\u0441\u043b\u043e \u00ab\u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u0434\u0435\u0442\u0435\u0439\u00bb \u043b\u0430\u0442\u0435\u043d\u0442\u0430); \u0444\u043e\u0440\u043c\u0430\u0442 \u0432\u044b\u0432\u043e\u0434\u0430 (PAG vs \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 DAG); \u0433\u0440\u0430\u0434\u0438\u0435\u043d\u0442\u043d\u0430\u044f \u043b\u0438 \u0443 CAMUV \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0446\u0438\u044f (\u0432\u043b\u0438\u044f\u0435\u0442 \u043d\u0430 runtime \u0431\u0435\u0437 GPU); \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c Sachs \u043a\u0430\u043a \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a\u0430.\n\n== 4. \u0422\u0435\u043c\u044b \u0434\u043b\u044f \u0442\u0432\u043e\u0438\u0445 \u0443\u0442\u043e\u0447\u043d\u0435\u043d\u0438\u0439 (\u0431\u044e\u0434\u0436\u0435\u0442 6) ==\n1) \u0421\u0442\u0430\u0442\u044c\u044f/\u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u043e\u0432\u043a\u0430 CAMUV: \u0442\u043e\u0447\u043d\u044b\u0435 \u043f\u0440\u0435\u0434\u043f\u043e\u0441\u044b\u043b\u043a\u0438 (\u043b\u0438\u043d\u0435\u0439\u043d\u043e\u0441\u0442\u044c, \u043d\u0435\u0433\u0430\u0443\u0441\u0441\u043e\u0432\u043e\u0441\u0442\u044c, max L, \u043a\u043e\u043b\u043b\u0430\u0439\u0434\u0435\u0440\u044b).\n2) \u0424\u043e\u0440\u043c\u0430\u0442 \u0432\u044b\u0432\u043e\u0434\u0430 CAMUV (\u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 DAG / PAG / \u044f\u0432\u043d\u044b\u0435 \u043b\u0430\u0442\u0435\u043d\u0442\u044b).\n3) \u0420\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f CAMUV: \u0434\u0430\u0451\u0442\u0441\u044f \u0438\u043b\u0438 \u0440\u0435\u0438\u043c\u043f\u043b\u0435\u043c\u0435\u043d\u0442.\n4) \u041f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044c \u043d\u0430\u0431\u043e\u0440 \u0431\u0430\u0437\u043b\u0430\u0439\u043d\u043e\u0432 (FCMP, LiNGAM, ICU-LiNGAM, random).\n5) \u0420\u0435\u0430\u043b\u044c\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435: \u0442\u043e\u043b\u044c\u043a\u043e Sachs \u0438\u043b\u0438 \u0434\u043e\u0431\u0430\u0432\u0438\u0442\u044c.\n6) \u0411\u044e\u0434\u0436\u0435\u0442 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u0439 \u0438 \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u044b (n, L, \u0447\u0438\u0441\u043b\u043e \u0440\u0435\u043f\u043b\u0438\u043a).\n\n\u041f\u043e\u043b\u043d\u044b\u0439 \u0434\u0438\u0437\u0430\u0439\u043d (\u0442\u0430\u0431\u043b\u0438\u0446\u044b \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432, \u0444\u043e\u0440\u043c\u0443\u043b\u044b \u043c\u0435\u0442\u0440\u0438\u043a, \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b) \u2014 \u043f\u043e\u0441\u043b\u0435 \u0442\u0432\u043e\u0435\u0433\u043e \u043e\u0434\u043e\u0431\u0440\u0435\u043d\u0438\u044f \u044d\u0442\u043e\u0433\u043e \u043f\u043b\u0430\u043d\u0430.", "evidence": "\u041f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u043e \u043a\u043e\u043c\u0430\u043d\u0434\u0430\u043c\u0438 \u0432 \u0441\u0440\u0435\u0434\u0435: (1) `find /workspace -type f` \u2192 \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0444\u0430\u0439\u043b /workspace/task.json (401 B); `ls -laR /workspace` \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u043a\u043e\u0434\u0430/\u0434\u0430\u0442\u0430\u0441\u0435\u0442\u043e\u0432/\u0434\u043e\u043a\u043e\u0432. (2) \u0421\u043e\u0434\u0435\u0440\u0436\u0438\u043c\u043e\u0435 task.json \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043d\u043e: question \u043f\u0440\u043e CAMUV, context \"Design an experiment... Do not claim that an experiment was run\", documents.track.md = \"Design-only task; repositories and compute are not required.\" (3) `python3 --version` \u2192 3.14.4; `python3 -c \"import numpy\"` \u0438 `import scipy` \u2192 ModuleNotFoundError; `pip list | grep -iE 'numpy|pandas|scipy|causal|lingam|torch'` \