38 Sachs \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b \u2014 \u0432\u0441\u0451 CAMUV-\u0441\u043f\u0435\u0446\u0438\u0444\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u043d\u0438\u0436\u0435 \u043f\u043e\u043c\u0435\u0447\u0435\u043d\u043e [\u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u0415] \u0441 \u043f\u043b\u0430\u043d\u043e\u043c \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438.\n\n## 1. Rationale \u2014 \u043f\u043e\u0447\u0435\u043c\u0443 \u0438\u043c\u0435\u043d\u043d\u043e \u044d\u0442\u0430 \u0441\u0445\u0435\u043c\u0430 \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442 \u043d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441\n\u0412\u043e\u043f\u0440\u043e\u0441: \u043a\u0430\u043a CAMUV \u043d\u0430\u0445\u043e\u0434\u0438\u0442 \u043f\u0440\u0438\u0447\u0438\u043d\u043d\u044b\u0435 \u0441\u0432\u044f\u0437\u0438 \u043f\u0440\u0438 \u043d\u0435\u0437\u0430\u043c\u0435\u0442\u043d\u044b\u0445 \u043e\u0431\u0449\u0438\u0445 \u043f\u0440\u0438\u0447\u0438\u043d\u0430\u0445. \u041a\u043b\u044e\u0447\u0435\u0432\u0430\u044f \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u0437\u0430\u0434\u0430\u0447\u0438: \u043f\u0440\u0438 \u043d\u0435\u0437\u0430\u043c\u0435\u0442\u043d\u044b\u0445 \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0435\u0440\u0430\u0445 \u0438\u0441\u0445\u043e\u0434\u043d\u044b\u0439 DAG **\u043d\u0435 \u0438\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u0435\u043c** \u043f\u043e \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u043c \u0434\u0430\u043d\u043d\u044b\u043c \u2014 \u0438\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u0435\u043c\u044b\u0439 \u043e\u0431\u044a\u0435\u043a\u0442 \u044d\u0442\u043e **\u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0433\u0440\u0430\u0444**: \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0435 \u0440\u0451\u0431\u0440\u0430 \u043c\u0435\u0436\u0434\u0443 \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u043c\u0438 + \u0434\u0432\u0443\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0435 \u0440\u0451\u0431\u0440\u0430 \u0434\u043b\u044f \u043f\u0430\u0440 \u0441 \u043e\u0431\u0449\u0438\u043c \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u043c \u043f\u0440\u0435\u0434\u043a\u043e\u043c. \u041f\u043e\u044d\u0442\u043e\u043c\u0443:\n1. **Ground truth \u0441\u0442\u0440\u043e\u0438\u0442\u0441\u044f \u043a\u0430\u043a \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0433\u0440\u0430\u0444** (\u043d\u0435 \u0438\u0441\u0445\u043e\u0434\u043d\u044b\u0439 DAG) \u2014 \u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u0438\u0437\u043c\u0435\u0440\u044f\u044e\u0442 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u0438\u043c\u0435\u043d\u043d\u043e \u0438\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u0435\u043c\u043e\u0433\u043e \u043e\u0431\u044a\u0435\u043a\u0442\u0430, \u0430 \u043d\u0435 \u0447\u0435\u0433\u043e-\u0442\u043e \u043d\u0435\u0434\u043e\u0441\u0442\u0438\u0436\u0438\u043c\u043e\u0433\u043e.\n2. **\u0421\u0438\u043d\u0442\u0435\u0442\u0438\u043a\u0430** \u0434\u0430\u0451\u0442 \u043f\u043e\u043b\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c: L (\u0447\u0438\u0441\u043b\u043e \u043b\u0430\u0442\u0435\u043d\u0442\u043e\u0432), \u043f\u043b\u043e\u0442\u043d\u043e\u0441\u0442\u044c \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u043d\u0433\u0430, n, \u043e\u0431\u044a\u0451\u043c \u0432\u044b\u0431\u043e\u0440\u043a\u0438, \u0442\u0438\u043f \u0448\u0443\u043c\u0430 \u2014 \u043c\u043e\u0436\u043d\u043e \u0438\u0437\u043e\u043b\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u043f\u0440\u0438 \u043a\u0430\u043a\u0438\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445 CAMUV \u043d\u0430\u0445\u043e\u0434\u0438\u0442 \u0441\u0432\u044f\u0437\u0438.\n3. **Controls** \u043e\u0442\u0434\u0435\u043b\u044f\u044e\u0442 \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c: C1 (L=0) \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442, \u0447\u0442\u043e \u043c\u0435\u0442\u043e\u0434 \u043d\u0435 \u00ab\u0433\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0438\u0440\u0443\u0435\u0442\u00bb \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u043d\u0433 \u0442\u0430\u043c, \u0433\u0434\u0435 \u0435\u0433\u043e \u043d\u0435\u0442 (\u043a\u0440\u0438\u0442\u0438\u0447\u043d\u043e \u0434\u043b\u044f \u0434\u043e\u0432\u0435\u0440\u0438\u044f \u043a \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0435\u043d\u043d\u044b\u043c \u0434\u0432\u0443\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u043c \u0440\u0451\u0431\u0440\u0430\u043c); C2 (\u0433\u0430\u0443\u0441\u0441\u043e\u0432 \u0448\u0443\u043c) \u043a\u0430\u0440\u0442\u0438\u0440\u0443\u0435\u0442 \u0433\u0440\u0430\u043d\u0438\u0446\u0443 \u043f\u0440\u0435\u0434\u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u043e \u043d\u0435\u0433\u0430\u0443\u0441\u0441\u043e\u0432\u043e\u0441\u0442\u0438; C3 \u2014 \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0435 \u0432\u043d\u0435 \u043c\u043e\u0434\u0435\u043b\u0438.\n4. **\u0411\u0430\u0437\u043b\u0430\u0439\u043d\u044b** \u0440\u0430\u0437\u043b\u0430\u0433\u0430\u044e\u0442 \u0432\u043a\u043b\u0430\u0434: LiNGAM (\u0431\u0435\u0437 \u043b\u0430\u0442\u0435\u043d\u0442\u043e\u0432) \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442, \u0447\u0442\u043e \u0438\u043c\u0435\u043d\u043d\u043e \u0434\u0430\u0451\u0442 \u0443\u0447\u0451\u0442 \u043b\u0430\u0442\u0435\u043d\u0442\u043e\u0432; FCMP \u0438 ICU-LiNGAM \u2014 \u043f\u0440\u044f\u043c\u044b\u0435 \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0442\u044b \u0441 \u043b\u0430\u0442\u0435\u043d\u0442\u0430\u043c\u0438; random \u2014 \u043d\u0438\u0436\u043d\u044f\u044f \u0433\u0440\u0430\u043d\u0438\u0446\u0430. \u041e\u0442\u0432\u0435\u0442 \u043d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441 \u2014 \u043d\u0435 \u00abCAMUV \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442/\u043d\u0435\u0442\u00bb, \u0430 \u00abCAMUV \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u0442 \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0433\u0440\u0430\u0444 \u043b\u0443\u0447\u0448\u0435/\u043d\u0435 \u0445\u0443\u0436\u0435 \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0442\u043e\u0432 \u043f\u0440\u0438 \u0442\u0430\u043a\u0438\u0445-\u0442\u043e \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445 \u0438 \u043d\u0435 \u0433\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0438\u0440\u0443\u0435\u0442 \u043f\u0440\u0438 \u0438\u0445 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0438\u00bb.\n5. **Sachs** \u2014 \u0432\u043d\u0435\u0448\u043d\u0438\u0439 \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0439 \u0447\u0435\u043a \u043d\u0430 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445 (\u0431\u0435\u0437 ground truth, \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0441 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u043c PAG).\n\n## 2. \u0420\u0430\u0437\u0434\u0435\u043b CAMUV-\u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0439 (\u0432\u0441\u0435 \u2014 [\u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u0415], \u0441 \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0435\u0439 \u0438 \u0430\u043d\u0430\u043b\u0438\u0437\u043e\u043c \u00ab\u0447\u0442\u043e \u043b\u043e\u043c\u0430\u0435\u0442\u0441\u044f\u00bb)\n\n| # | \u0414\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435 | \u0412\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f (\u0448\u0430\u0433) | \u0427\u0442\u043e \u043b\u043e\u043c\u0430\u0435\u0442\u0441\u044f, \u0435\u0441\u043b\u0438 \u043d\u0435\u0432\u0435\u0440\u043d\u043e |\n|---|-----------|-------------------|----------------------------|\n| A1 | \u041c\u043e\u0434\u0435\u043b\u044c CAMUV: \u043b\u0438\u043d\u0435\u0439\u043d\u044b\u0435 SEM, **\u043d\u0435\u0433\u0430\u0443\u0441\u0441\u043e\u0432\u044b\u0439** \u0448\u0443\u043c, \u043b\u0430\u0442\u0435\u043d\u0442\u044b \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u043e\u0431\u0449\u0438\u0435 \u043f\u0440\u0438\u0447\u0438\u043d\u044b \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u0445 \u043f\u0430\u0440, \u043d\u0435\u0442 \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u0445 \u043a\u043e\u043b\u043b\u0430\u0439\u0434\u0435\u0440\u043e\u0432, \u043d\u0435\u0442 \u0441\u0432\u044f\u0437\u0435\u0439 \u043b\u0430\u0442\u0435\u043d\u0442\u2194\u043b\u0430\u0442\u0435\u043d\u0442, \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435 \u043d\u0430 \u0447\u0438\u0441\u043b\u043e \u0434\u0435\u0442\u0435\u0439 \u043b\u0430\u0442\u0435\u043d\u0442\u0430 (K_max) | \u0424\u0430\u0437\u0430 0: \u043f\u043e\u043b\u0443\u0447\u0438\u0442\u044c \u0441\u0442\u0430\u0442\u044c\u044e CAMUV (\u0442\u0435\u043c\u0430 \u0443\u0442\u043e\u0447\u043d\u0435\u043d\u0438\u044f 1); \u0441\u0432\u0435\u0440\u0438\u0442\u044c \u0443\u0441\u043b\u043e\u0432\u0438\u044f \u0438\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u0435\u043c\u043e\u0441\u0442\u0438 | \u0413\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440 \u0434\u0430\u043d\u043d\u044b\u0445 (\u00a73) \u0434\u043e\u043b\u0436\u0435\u043d \u0431\u044b\u0442\u044c \u043f\u0435\u0440\u0435\u043f\u0438\u0441\u0430\u043d \u043f\u043e\u0434 \u0440\u0435\u0430\u043b\u044c\u043d\u0443\u044e \u043c\u043e\u0434\u0435\u043b\u044c; \u0435\u0441\u043b\u0438 \u0435\u0441\u0442\u044c K_max \u2014 \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440 \u043e\u0431\u044f\u0437\u0430\u043d \u0435\u0433\u043e \u0441\u043e\u0431\u043b\u044e\u0434\u0430\u0442\u044c, \u0438\u043d\u0430\u0447\u0435 ground truth \u043d\u0435\u0441\u043f\u0440\u0430\u0432\u0435\u0434\u043b\u0438\u0432 (\u043c\u0435\u0442\u043e\u0434 \u00ab\u043f\u0440\u043e\u0432\u0430\u043b\u0438\u0442\u0441\u044f\u00bb \u0442\u0435\u043e\u0440\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438, \u043d\u0435 \u044d\u043c\u043f\u0438\u0440\u0438\u0447\u0435\u0441\u043a\u0438). C2/C3 \u043f\u0435\u0440\u0435\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u044e\u0442\u0441\u044f |\n| A2 | \u0412\u044b\u0445\u043e\u0434 CAMUV \u2014 **\u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0433\u0440\u0430\u0444** (\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0435 + \u0434\u0432\u0443\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0435 \u0440\u0451\u0431\u0440\u0430), \u043d\u0435 PAG, \u043d\u0435 \u044f\u0432\u043d\u044b\u0435 \u043b\u0430\u0442\u0435\u043d\u0442\u044b | \u0424\u0430\u0437\u0430 0: \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0432 \u0441\u0442\u0430\u0442\u044c\u0435 / API \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 | \u0415\u0441\u043b\u0438 \u0432\u044b\u0445\u043e\u0434 PAG \u2192 \u043c\u0435\u0442\u0440\u0438\u043a\u0438 (\u00a76) \u043f\u0435\u0440\u0435\u043a\u043b\u044e\u0447\u0430\u044e\u0442\u0441\u044f \u043d\u0430 PAG-representation, ground truth \u0441\u0442\u0440\u043e\u0438\u0442\u0441\u044f \u043c\u043e\u0440\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0435\u0439+\u0447\u0430\u0441\u0442\u0438\u0447\u043d\u043e\u0439 \u043e\u0440\u0438\u0435\u043d\u0442\u0430\u0446\u0438\u0435\u0439 (\u0434\u043e\u043f. \u0448\u0430\u0433). \u0415\u0441\u043b\u0438 \u044f\u0432\u043d\u044b\u0435 \u043b\u0430\u0442\u0435\u043d\u0442\u044b \u2192 \u043d\u0443\u0436\u0435\u043d \u0448\u0430\u0433 \u043c\u0430\u0442\u0447\u0438\u043d\u0433\u0430 \u043b\u0430\u0442\u0435\u043d\u0442\u043e\u0432 (\u0437\u0430\u0434\u0430\u0447\u0430 \u043e \u043d\u0430\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0438) \u0434\u043e \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f \u2014 \u0434\u043e\u0431\u0430\u0432\u043b\u044f\u0435\u0442 \u043e\u0448\u0438\u0431\u043a\u0443 \u0438 \u0441\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u044c |\n| A3 | \u041f\u0443\u0431\u043b\u0438\u0447\u043d\u0430\u044f \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f CAMUV \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u0435\u0442 | \u0424\u0430\u0437\u0430 0: \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0439 (\u043d\u0443\u0436\u043d\u0430 \u0441\u0435\u0442\u044c) \u0438\u043b\u0438 \u0443\u0442\u043e\u0447\u043d\u0435\u043d\u0438\u0435 \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044f (\u0442\u0435\u043c\u0430 3) | \u0411\u043b\u043e\u043a \u043d\u0430 \u0432\u0435\u0441\u044c \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u2192 fallback \u00a78 (\u0440\u0435\u0438\u043c\u043f\u043b\u0435\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u044f \u043a\u0430\u043a \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u0430\u044f \u0440\u0430\u0431\u043e\u0447\u0430\u044f \u0437\u0430\u0434\u0430\u0447\u0430) |\n| A4 | \u0411\u0430\u0437\u043b\u0430\u0439\u043d\u044b \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b: FCMP \u0438 LiNGAM \u0432 causal-learn; ICU-LiNGAM \u2014 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u0439 \u043a\u043e\u0434 | \u0424\u0430\u0437\u0430 1: \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 \u043f\u0430\u043a\u0435\u0442\u043e\u0432 | \u0415\u0441\u043b\u0438 ICU-LiNGAM \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d \u2014 \u0432\u044b\u043a\u0438\u0434\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u043e\u0434\u0438\u043d \u0431\u0430\u0437\u043b\u0430\u0439\u043d, \u0434\u0438\u0437\u0430\u0439\u043d \u0434\u0435\u0433\u0440\u0430\u0434\u0438\u0440\u0443\u0435\u0442 gracefully (H1 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u043f\u0440\u043e\u0442\u0438\u0432 FCMP + LiNGAM + random). \u0415\u0441\u043b\u0438 causal-learn \u043d\u0435 \u0441\u0442\u0430\u0432\u0438\u0442\u0441\u044f \u043d\u0430 Python 3.14 \u2014 \u043d\u0443\u0436\u0435\u043d \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043e\u0431\u0440\u0430\u0437 3.10\u20133.12 (\u00a77) |\n| A5 | Sachs (111\u00d711) \u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d \u043d\u0430 \u043c\u043e\u043c\u0435\u043d\u0442 \u0437\u0430\u043f\u0443\u0441\u043a\u0430 | \u0424\u0430\u0437\u0430 1: \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c; \u0444\u0430\u0439\u043b \u043c\u0430\u043b \u2014 \u043c\u043e\u0436\u043d\u043e \u0432\u0441\u0442\u0440\u043e\u0438\u0442\u044c \u0432 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0439 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430 | \u0420\u0435\u0430\u043b\u044c\u043d\u0430\u044f \u0447\u0430\u0441\u0442\u044c \u043e\u0442\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u0442\u0441\u044f, H3 = N/A; \u044f\u0434\u0440\u043e (\u0441\u0438\u043d\u0442\u0435\u0442\u0438\u043a\u0430) \u0432\u0441\u0451 \u0435\u0449\u0451 \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442 \u043d\u0430 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0432\u043e\u043f\u0440\u043e\u0441 \u2014 \u043f\u043e\u043c\u0435\u0447\u0430\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435 |\n| A6 | CAMUV \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043c \u043d\u0430 CPU (\u043d\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 GPU) | \u0424\u0430\u0437\u0430 2 (smoke): \u0437\u0430\u043c\u0435\u0440 \u0432\u0440\u0435\u043c\u0435\u043d\u0438 | \u0415\u0441\u043b\u0438 CAMUV \u0433\u0440\u0430\u0434\u0438\u0435\u043d\u0442\u043d\u044b\u0439/NN \u0438 \u043c\u0435\u0434\u043b\u0435\u043d\u043d\u044b\u0439 \u043d\u0430 CPU \u2014 \u0433\u0440\u0435\u0439\u0434\u044b \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u0430 \u0443\u0440\u0435\u0437\u0430\u044e\u0442\u0441\u044f (n, m), \u043f\u043e\u043c\u0435\u0447\u0430\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435 \u0434\u0438\u0437\u0430\u0439\u043d\u0430 |\n\n**\u041f\u043e\u0440\u044f\u0434\u043e\u043a \u043a\u0440\u0438\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u0438:** A1 \u2192 A2 \u2192 A3. \u0424\u0430\u0437\u0430 0 \u2014 gate: \u0431\u0435\u0437 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u044f A1\u2013A3 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u043d\u0435 \u0441\u0442\u0430\u0440\u0442\u0443\u0435\u0442.\n\n## 3. \u0414\u0430\u043d\u043d\u044b\u0435\n\n### 3.1 \u0421\u0438\u043d\u0442\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440 (\u043e\u0441\u043d\u043e\u0432\u043d\u0430\u044f \u0447\u0430\u0441\u0442\u044c)\n\u041c\u043e\u0434\u0435\u043b\u044c: \u043b\u0438\u043d\u0435\u0439\u043d\u044b\u0439 SEM x_j = \u03a3_i w_ij\u00b7x_i + e_j, e_j \u2014 \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0439 \u043d\u0435\u0433\u0430\u0443\u0441\u0441\u043e\u0432\u044b\u0439 \u0448\u0443\u043c. \u0412\u044b\u0445\u043e\u0434\u044b \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u0438\u0437\u0438\u0440\u0443\u044e\u0442\u0441\u044f.\n\n| \u041f\u0430\u0440\u0430\u043c\u0435\u0442\u0440 | \u0417\u043d\u0430\u0447\u0435\u043d\u0438\u044f | \u041a\u043e\u043c\u043c\u0435\u043d\u0442\u0430\u0440\u0438\u0439 |\n|---|---|---|\n| n (\u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u0445) | 10, 20, 50 | \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439: 10, 20, 50 |\n| p (\u043f\u043b\u043e\u0442\u043d\u043e\u0441\u0442\u044c DAG) | 0.15 (\u044f\u0434\u0440\u043e); 0.05, 0.1, 0.2 (\u0440\u0430\u0441\u0448\u0438\u0440.) | Erd\u0151s\u2013R\u00e9nyi DAG |\n| L (\u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u0445) | 0, 1, 2, 3 | L=0 = \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c C1 |\n| k_i (\u0434\u0435\u0442\u0435\u0439 \u043b\u0430\u0442\u0435\u043d\u0442\u0430 i) | 2, 3, 4 | \u0432\u0435\u0440\u0445\u043d\u044f\u044f \u0433\u0440\u0430\u043d\u0438\u0446\u0430 = min(4, K_max \u0438\u0437 A1) |\n| \u0428\u0443\u043c e_j | \u041b\u0430\u043f\u043b\u0430\u0441 (\u043e\u0441\u043d.); exp-Gaussian (\u0440\u0430\u0441\u0448\u0438\u0440.); \u0413\u0430\u0443\u0441\u0441 (\u0442\u043e\u043b\u044c\u043a\u043e C2) | \u043d\u0435\u0433\u0430\u0443\u0441\u0441\u043e\u0432\u043e\u0441\u0442\u044c \u043f\u043e A1 |\n| m (\u0432\u044b\u0431\u043e\u0440\u043a\u0430) | 1000, 5000 (\u044f\u0434\u0440\u043e); 500, 2000, 10000 (\u0440\u0430\u0441\u0448\u0438\u0440.) | |\n| w_ij | U(\u22121,1) \\ {0} | \u0430\u0446\u0438\u043a\u043b\u0438\u0447\u043d\u043e\u0441\u0442\u044c \u0433\u0430\u0440\u0430\u043d\u0442\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0442\u043e\u043f\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0441\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u043a\u043e\u0439 |\n\n\u041e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440\u0430 (guardrails, \u0437\u0430\u0432\u0438\u0441\u044f\u0442 \u043e\u0442 A1): \u043b\u0430\u0442\u0435\u043d\u0442 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u043e\u0431\u0449\u0438\u0439 \u043f\u0440\u0435\u0434\u043e\u043a \u0441\u0432\u043e\u0435\u0433\u043e \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0430 \u0434\u0435\u0442\u0435\u0439; \u043d\u0435\u0442 \u0440\u0451\u0431\u0435\u0440 \u043b\u0430\u0442\u0435\u043d\u0442\u2194\u043b\u0430\u0442\u0435\u043d\u0442; \u043d\u0435\u0442 \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u0445 \u043a\u043e\u043b\u043b\u0430\u0439\u0434\u0435\u0440\u043e\u0432 (\u044f\u0434\u0440\u043e); \u043d\u0435\u0442 \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u0445 \u043a\u043e\u043b\u043b\u0430\u0439\u0434\u0435\u0440\u043e\u0432 (\u044f\u0434\u0440\u043e). \u041a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u043f\u0430\u0440\u0430 = \u0434\u0432\u0435 \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u0435 \u0441 \u043e\u0431\u0449\u0438\u043c \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u043c \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u043c; \u0438\u0441\u0442\u0438\u043d\u043d\u044b\u0439 \u043d\u0430\u0431\u043e\u0440 \u0442\u0430\u043a\u0438\u0445 \u043f\u0430\u0440 \u2014 \u0447\u0430\u0441\u0442\u044c ground truth.\n\n**Unit-\u0442\u0435\u0441\u0442\u044b \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440\u0430 (\u0424\u0430\u0437\u0430 1):** (\u0430) \u0430\u0446\u0438\u043a\u043b\u0438\u0447\u043d\u043e\u0441\u0442\u044c; (\u0431) \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u043d\u044b\u0439 \u043d\u0430\u0431\u043e\u0440 \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u043f\u0430\u0440 \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u0435\u0442 \u0441 \u0437\u0430\u0434\u0430\u043d\u043d\u044b\u043c; (\u0432) \u0442\u0435\u0441\u0442\u044b \u043d\u0430 \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0448\u0443\u043c\u0430 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u043d\u0430 \u0430\u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u044e/\u044d\u043a\u0441\u0446\u0435\u0441\u0441 \u0434\u043b\u044f \u041b\u0430\u043f\u043b\u0430\u0441\u0430 vs \u0413\u0430\u0443\u0441\u0441\u0430); (\u0433) \u043a\u043e\u0432\u0430\u0440\u0438\u0430\u0446\u0438\u043e\u043d\u043d\u0430\u044f \u0441\u0438\u0433\u043d\u0430\u0442\u0443\u0440\u0430: \u0443 \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u043f\u0430\u0440 \u0447\u0430\u0441\u0442\u0438\u0447\u043d\u0430\u044f \u043a\u043e\u0432\u0430\u0440\u0438\u0430\u0446\u0438\u044f \u2260 0 \u043f\u0440\u0438 \u0443\u0441\u043b\u043e\u0432\u043b\u0438\u0432\u0430\u043d\u0438\u0438 \u043d\u0430 \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u0435.\n\n### 3.2 \u0420\u0435\u0430\u043b\u044c\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435\nSachs (m=111, n=11). Reference: PAG \u0438\u0437 \u043b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u044b. Ground truth \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u2192 H3 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439: \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b CAMUV \u0441 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u043c PAG \u0438 \u0441 \u043a\u043e\u043d\u0441\u0435\u043d\u0441\u0443\u0441\u043e\u043c \u0431\u0430\u0437\u043b\u0430\u0439\u043d\u043e\u0432 (\u043c\u0430\u0442\u0440\u0438\u0446\u0430 \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u0438\u044f \u0440\u0451\u0431\u0435\u0440). \u041e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e: subsampling-bootstrap \u00d7100 \u0434\u043b\u044f \u043e\u0446\u0435\u043d\u043a\u0438 \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u0438 (n=111 \u043c\u0430\u043b \u2014 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0430, \u043f\u043e\u043c\u0435\u0447\u0435\u043d\u043e).\n\n## 4. \u041c\u0435\u0442\u043e\u0434\u044b \u0438 \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0432\u044b\u0445\u043e\u0434\u043e\u0432\n| \u041c\u0435\u0442\u043e\u0434 | \u0420\u043e\u043b\u044c | \u041b\u0430tent-aware |\n|---|---|---|\n| CAMUV | \u043e\u0431\u044a\u0435\u043a\u0442 \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u044f | \u0434\u0430 |\n| FCMP (f-cMVP) | \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0442 | \u0434\u0430 |\n| LiNGAM | \u0431\u0430\u0437\u043b\u0430\u0439\u043d \u0431\u0435\u0437 \u043b\u0430\u0442\u0435\u043d\u0442\u043e\u0432 (\u043e\u0436\u0438\u0434\u0430\u0435\u043c\u043e \u0441\u043b\u0430\u0431 \u043f\u0440\u0438 \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u043d\u0433\u0435) | \u043d\u0435\u0442 |\n| ICU-LiNGAM | \u043f\u0440\u044f\u043c\u043e\u0439 \u0430\u043d\u0430\u043b\u043e\u0433 (LiNGAM + \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u0435 \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0435\u0440\u044b) | \u0434\u0430 |\n| Random-DAG | \u043d\u0438\u0436\u043d\u044f\u044f \u0433\u0440\u0430\u043d\u0438\u0446\u0430: \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0439 DAG \u0442\u043e\u0439 \u0436\u0435 \u043f\u043b\u043e\u0442\u043d\u043e\u0441\u0442\u0438 p | \u043d\u0435\u0442 |\n| Random-PAG | \u043d\u0438\u0436\u043d\u044f\u044f \u0433\u0440\u0430\u043d\u0438\u0446\u0430: \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0439 \u0433\u0440\u0430\u0444 \u0441 \u0442\u0435\u043c \u0436\u0435 \u0447\u0438\u0441\u043b\u043e\u043c \u0434\u0432\u0443\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0445 \u0440\u0451\u0431\u0435\u0440, \u0447\u0442\u043e \u0432 ground truth | \u00ab\u0434\u0430\u00bb (\u0441\u043b\u0443\u0447\u0430\u0439\u043d\u043e) |\n\n**\u041d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f:** \u0432\u044b\u0445\u043e\u0434 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u043c\u0435\u0442\u043e\u0434\u0430 \u043f\u0440\u0438\u0432\u043e\u0434\u0438\u0442\u0441\u044f \u043a \u043e\u0431\u0449\u0435\u043c\u0443 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u044e \u2014 \u0433\u0440\u0430\u0444 \u043d\u0430\u0434 \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u043c\u0438 \u0441 \u043a\u043b\u0430\u0441\u0441\u0430\u043c\u0438 \u0440\u0451\u0431\u0435\u0440 {\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u043e\u0435, \u0434\u0432\u0443\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u043e\u0435, \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0435}. \u0414\u043b\u044f LiNGAM/Random-DAG: \u0434\u0432\u0443\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0445 \u043d\u0435\u0442. \u0414\u043b\u044f PAG-\u0432\u044b\u0445\u043e\u0434\u043e\u0432 (FCMP, \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e CAMUV \u043f\u0440\u0438 \u043e\u043f\u0440\u043e\u0432\u0435\u0440\u0436\u0435\u043d\u0438\u0438 A2): \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u044b\u0435 \u0440\u0451\u0431\u0440\u0430 \u0443\u0447\u0438\u0442\u044b\u0432\u0430\u044e\u0442\u0441\u044f \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e (\u0441\u0447\u0451\u0442 \u00ab\u0447\u0430\u0441\u0442\u0438\u0447\u043d\u043e \u0432\u0435\u0440\u043d\u043e\u00bb \u0437\u0430\u0434\u0443\u043c\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0437\u0430\u0440\u0430\u043d\u0435\u0435: \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0435, \u0438\u0441\u0442\u0438\u043d\u043d\u043e \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0435 = 0.5; \u0432 \u044f\u0434\u0440\u0435 ground truth \u0431\u0435\u0437 \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u044b\u0445 \u2014 0).\n\n## 5. Controls (\u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043e)\n- **C1 (\u044f\u0434\u0440\u043e, \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e): L=0** \u043f\u0440\u0438 \u0442\u0435\u0445 \u0436\u0435 n, p, m, \u0448\u0443\u043c\u0435. \u041a\u0440\u0438\u0442\u0435\u0440\u0438\u0439: CAMUV \u043d\u0435 \u0432\u044b\u0434\u0430\u0451\u0442 \u0434\u0432\u0443\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0445 \u0440\u0451\u0431\u0435\u0440 (\u0430\u043d\u0442\u0438\u0433\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0430\u0446\u0438\u044f) \u0438 \u043d\u0435 \u0442\u0435\u0440\u044f\u0435\u0442 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u043e \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0445 \u0440\u0451\u0431\u0435\u0440.\n- **C2 (\u044f\u0434\u0440\u043e, \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e): \u0433\u0430\u0443\u0441\u0441\u043e\u0432\u044b\u0439 \u0448\u0443\u043c**, L\u2208{1,2,3}, n=20, m=5000. \u041a\u0440\u0438\u0442\u0435\u0440\u0438\u0439: \u0434\u0435\u0433\u0440\u0430\u0434\u0430\u0446\u0438\u044f \u2192 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442, \u0447\u0442\u043e \u043d\u0435\u0433\u0430\u0443\u0441\u0441\u043e\u0432\u043e\u0441\u0442\u044c \u2014 \u043d\u0435\u0441\u0443\u0449\u0435\u0435 \u043f\u0440\u0435\u0434\u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u0435; \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u0434\u0435\u0433\u0440\u0430\u0434\u0430\u0446\u0438\u0438 \u2192 \u043f\u0435\u0440\u0435\u0441\u043c\u043e\u0442\u0440 A1.\n- **C3 (\u0420\u0415\u0428\u0415\u041d\u041e: \u0432\u043a\u043b\u044e\u0447\u0451\u043d \u0442\u043e\u043b\u044c\u043a\u043e \u0432 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u043d\u044b\u0439 \u0442\u0438\u0440, \u043a\u0430\u043a \u0434\u0438\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439, \u0431\u0435\u0437 \u0433\u0438\u043f\u043e\u0442\u0435\u0437\u044b):** \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u0439 \u043a\u043e\u043b\u043b\u0430\u0439\u0434\u0435\u0440 (1 \u043b\u0430\u0442\u0435\u043d\u0442, \u0440\u043e\u0432\u043d\u043e 2 \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u0445 \u0440\u0435\u0431\u0451\u043d\u043a\u0430, \u043e\u0431\u0440\u0430\u0437\u0443\u044e\u0449\u0438\u0445 \u043a\u043e\u043b\u043b\u0430\u0439\u0434\u0435\u0440), n=10, p=0.1, m=2000, R=20. \u0420\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c \u0440\u0435\u0448\u0435\u043d\u0438\u044f: \u043a\u043e\u043b\u043b\u0430\u0439\u0434\u0435\u0440\u044b \u0432\u043d\u0435 \u043c\u043e\u0434\u0435\u043b\u0438 A1, \u0442.\u0435. \u044d\u0442\u043e \u0437\u043e\u043d\u0434 \u0440\u043e\u0431\u0430\u0441\u0442\u043d\u043e\u0441\u0442\u0438 \u0432\u043d\u0435 \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438 \u2014 \u0432\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435 \u0432 \u044f\u0434\u0440\u043e \u0440\u0430\u0437\u043c\u044b\u0432\u0430\u043b\u043e \u0431\u044b \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u044e H1; \u043e\u0442\u0447\u0451\u0442 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u0435 \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u044f, \u043d\u0438\u043a\u0430\u043a\u0438\u0445 success-\u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0435\u0432.\n\n## 6. \u041f\u043b\u0430\u043d \u0430\u043d\u0430\u043b\u0438\u0437\u0430\n\n### \u041c\u0435\u0442\u0440\u0438\u043a\u0438\n- **Directed F1**: TP \u2014 \u0432\u0435\u0440\u043d\u043e \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u043e\u0435; FP \u2014 \u043b\u0438\u0448\u043d\u0435\u0435 \u0438\u043b\u0438 \u043f\u0435\u0440\u0435\u0432\u0451\u0440\u043d\u0443\u0442\u043e\u0435; FN \u2014 \u043f\u0440\u043e\u043f\u0443\u0449\u0435\u043d\u043d\u043e\u0435.\n- **Bidirected F1**: TP \u2014 \u043f\u0430\u0440\u0430 \u0441 \u043e\u0431\u0449\u0438\u043c \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u043c \u043f\u0440\u0435\u0434\u043a\u043e\u043c \u0432 ground truth; FP \u2014 \u0434\u0432\u0443\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u043e\u0435 \u0431\u0435\u0437 \u043e\u0431\u0449\u0435\u0433\u043e \u043f\u0440\u0435\u0434\u043a\u0430 (\u0432\u043a\u043b. \u00ab\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u043e\u0435 \u0438\u0441\u0442\u0438\u043d\u043d\u043e \u2192 \u0434\u0432\u0443\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u043e\u0435 \u0438\u0441\u0442\u0438\u043d\u043d\u043e\u00bb); FN \u2014 \u043f\u0440\u043e\u043f\u0443\u0449\u0435\u043d\u043d\u0430\u044f \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u043f\u0430\u0440\u0430.\n- **SHD** (\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043d\u043e\u0435 \u0433\u044d\u043c\u043c\u0438\u043d\u0433-\u0440\u0430\u0441\u0441\u0442\u043e\u044f\u043d\u0438\u0435 \u043f\u043e \u043a\u043b\u0430\u0441\u0441\u0430\u043c): \u043b\u0438\u0448\u043d\u0435\u0435/\u043f\u0440\u043e\u043f\u0443\u0449\u0435\u043d\u043d\u043e\u0435 = 1, \u043f\u0435\u0440\u0435\u0432\u0451\u0440\u043d\u0443\u0442\u043e\u0435 = 2, \u0441\u043c\u0435\u043d\u0430 \u043a\u043b\u0430\u0441\u0441\u0430 = 2.\n- **C1-\u0441\u043f\u0435\u0446\u0438\u0444\u0438\u0447\u043d\u043e**: false-bidirected rate = \u0447\u0438\u0441\u043b\u043e \u0432\u044b\u0434\u0430\u043d\u043d\u044b\u0445 \u0434\u0432\u0443\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0445 \u0440\u0451\u0431\u0435\u0440 (\u0438\u0441\u0442\u0438\u043d\u0430: 0) + Directed F1 (\u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430, \u0447\u0442\u043e \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u0430\u044f \u043c\u0435\u0445\u0430\u043d\u0438\u043a\u0430 \u043d\u0435 \u043c\u0435\u0448\u0430\u0435\u0442).\n- Runtime \u0438 \u043f\u0438\u043a \u043f\u0430\u043c\u044f\u0442\u0438 \u043d\u0430 run.\n- Sachs: \u043c\u0430\u0442\u0440\u0438\u0446\u0430 \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u0438\u044f \u0440\u0451\u0431\u0435\u0440 \u0441 \u043b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u043d\u044b\u043c PAG \u0438 \u0441 \u043a\u043e\u043d\u0441\u0435\u043d\u0441\u0443\u0441\u043e\u043c \u0431\u0430\u0437\u043b\u0430\u0439\u043d\u043e\u0432 (\u0431\u0435\u0437 F1 \u2014 \u043d\u0435\u0442 ground truth).\n\n### \u0421\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430\n- \u041d\u0430 \u044f\u0447\u0435\u0439\u043a\u0443: \u0441\u0440\u0435\u0434\u043d\u0435\u0435 \u00b1 bootstrap 95% CI (1000 \u0440\u0435\u0441\u044d\u043c\u043f\u043b\u0438\u043d\u0433 \u043f\u043e \u0440\u0435\u043f\u043b\u0438\u043a\u0430\u043c R).\n- \u0421\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f \u043c\u0435\u0442\u043e\u0434\u043e\u0432 \u0432\u043d\u0443\u0442\u0440\u0438 \u044f\u0447\u0435\u0439\u043a\u0438: paired bootstrap \u0440\u0430\u0437\u043d\u0438\u0446\u044b (\u0438/\u0438\u043b\u0438 Wilcoxon signed-rank \u043f\u043e R), p<0.05; \u043a\u043e\u0440\u0440\u0435\u043a\u0446\u0438\u044f \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u0438 BH \u043f\u043e \u044f\u0447\u0435\u0439\u043a\u0430\u043c \u0434\u043b\u044f \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u0445 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0439.\n- \u041e\u0441\u043d\u043e\u0432\u043d\u044b\u0435 (primary) \u044d\u043d\u0434\u043f\u043e\u0438\u043d\u0442\u044b: **Bidirected F1** \u0438 **SHD**.\n\n### \u041a\u0440\u0438\u0442\u0435\u0440\u0438\u0438 \u0443\u0441\u043f\u0435\u0445\u0430/\u043d\u0435\u0443\u0434\u0430\u0447\u0438 H1\u2013H3 (\u043f\u0440\u0435\u0434\u0437\u0430\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435; \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u0435 \u0438\u0441\u0445\u043e\u0434\u044b, \u043d\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b)\n- **H1** (CAMUV \u043d\u0430\u0445\u043e\u0434\u0438\u0442 \u043f\u0440\u0438\u0447\u0438\u043d\u043d\u044b\u0435 \u0441\u0432\u044f\u0437\u0438 \u043f\u0440\u0438 \u043d\u0435\u0437\u0430\u043c\u0435\u0442\u043d\u044b\u0445 \u043e\u0431\u0449\u0438\u0445 \u043f\u0440\u0438\u0447\u0438\u043d\u0430\u0445): \u041e\u0416\u0418\u0414\u0410\u041d\u0418\u0415 \u2014 CAMUV \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0437\u043d\u0430\u0447\u0438\u043c\u043e \u043b\u0443\u0447\u0448\u0435 LiNGAM \u0438 Random \u0432 **\u0432\u0441\u0435\u0445** \u044f\u0447\u0435\u0439\u043a\u0430\u0445 \u0441 L\u22651 \u043f\u043e Bidirected F1 (\u0442\u0440\u0438\u0432\u0438\u0430\u043b\u044c\u043d\u043e \u043f\u043e Bidirected, \u0440\u0430\u0437 LiNGAM/Random-DAG \u043d\u0435 \u0432\u044b\u0434\u0430\u044e\u0442 bidirected, \u2014 \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0442\u0438\u0432\u0435\u043d SHD \u0438 Directed F1: CAMUV \u0434\u043e\u043b\u0436\u0435\u043d \u043d\u0435 \u0443\u0441\u0442\u0443\u043f\u0430\u0442\u044c) \u0438 **\u043d\u0435 \u0443\u0441\u0442\u0443\u043f\u0430\u0442\u044c** (SHD_CAMUV \u2264 SHD_best_latent + 0, \u0442.\u0435. \u0441\u0442\u0440\u043e\u0433\u043e\u0435 non-inferiority) \u043b\u0443\u0447\u0448\u0435\u043c\u0443 \u0438\u0437 FCMP/ICU-LiNGAM \u0432 \u226560% \u044f\u0447\u0435\u0435\u043a \u0441 L\u22651. \u041d\u0415\u0423\u0414\u0410\u0427\u0410 \u2014 \u043f\u0440\u043e\u0438\u0433\u0440\u044b\u0448 latent-aware \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0442\u0430\u043c \u0432 >50% \u044f\u0447\u0435\u0435\u043a \u2192 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0443\u0441\u043b\u043e\u0432\u0438\u044f (L, m, p), \u0433\u0434\u0435 CAMUV \u0432\u044b\u0438\u0433\u0440\u044b\u0432\u0430\u0435\u0442/\u043f\u0440\u043e\u0438\u0433\u0440\u044b\u0432\u0430\u0435\u0442.\n- **H2** (\u043d\u0435 \u0433\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0438\u0440\u0443\u0435\u0442): \u041e\u0416\u0418\u0414\u0410\u041d\u0418\u0415 \u2014 \u0432 C1 \u0441\u0440\u0435\u0434\u043d\u0435\u0435 \u0447\u0438\u0441\u043b\u043e \u043b\u043e\u0436\u043d\u044b\u0445 \u0434\u0432\u0443\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0445 \u0440\u0451\u0431\u0435\u0440 \u043d\u0430 run \u2264 0.1 \u0438 Directed F1 CAMUV \u043d\u0435 \u043d\u0438\u0436\u0435 Directed F1 LiNGAM \u0432 C1. \u041d\u0415\u0423\u0414\u0410\u0427\u0410 \u2014 \u0441\u0438\u0441\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043b\u043e\u0436\u043d\u044b\u0435 bidirected \u2192 \u043a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 (\u043c\u0435\u0442\u043e\u0434 \u043d\u0430\u0445\u043e\u0434\u0438\u0442 \u00ab\u043e\u0431\u0449\u0438\u0435 \u043f\u0440\u0438\u0447\u0438\u043d\u044b\u00bb \u0442\u0430\u043c, \u0433\u0434\u0435 \u0438\u0445 \u043d\u0435\u0442).\n- **H3** (\u0432\u043d\u0435\u0448\u043d\u044f\u044f \u0432\u0430\u043b\u0438\u0434\u043d\u043e\u0441\u0442\u044c): \u041e\u0416\u0418\u0414\u0410\u041d\u0418\u0415 \u2014 \u0432\u044b\u0445\u043e\u0434 CAMUV \u043d\u0430 Sachs \u043d\u0435 \u043f\u0440\u043e\u0442\u0438\u0432\u043e\u0440\u0435\u0447\u0438\u0442 \u0441\u0438\u043b\u044c\u043d\u043e \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u043c\u044b\u043c \u0440\u0451\u0431\u0440\u0430\u043c \u043b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u043d\u043e\u0433\u043e PAG \u0438 \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d \u0441 \u043d\u0438\u043c \u043d\u0435 \u0445\u0443\u0436\u0435 \u0431\u0430\u0437\u043b\u0430\u0439\u043d\u043e\u0432. (\u041a\u0430\u0447\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e; n=111 \u043d\u0435 \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u2014 \u043f\u043e\u043c\u0435\u0447\u0435\u043d\u043e.)\n- \u0412\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0435: C2 (\u0434\u0435\u0433\u0440\u0430\u0434\u0430\u0446\u0438\u044f \u043f\u0440\u0438 \u0433\u0430\u0443\u0441\u0441\u0435 = \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u043e), C3 (\u043e\u043f\u0438\u0441\u0430\u043d\u0438\u0435), runtime.\n\n## 7. Feasibility: staged budget (\u0431\u0435\u0437 \u0432\u044b\u0434\u0443\u043c\u0430\u043d\u043d\u044b\u0445 \u0446\u0438\u0444\u0440)\n\n**\u0424\u043e\u0440\u043c\u0443\u043b\u0430 \u0432\u0440\u0435\u043c\u0435\u043d\u0438:**\n`T_total(tier) = N_cells(tier) \u00d7 R(tier) \u00d7 (t_gen + t_CAMUV + \u03a3_b t_b)`\n\u0433\u0434\u0435 t_gen \u2014 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f (\u043f\u043e\u0440\u044f\u0434\u043a\u0430 O(n\u00b7m), \u043f\u0440\u0435\u043d\u0435\u0431\u0440\u0435\u0436\u0438\u043c\u043e), t_X \u2014 \u0432\u0440\u0435\u043c\u044f \u043e\u0434\u043d\u043e\u0433\u043e run \u043c\u0435\u0442\u043e\u0434\u0430 X, **\u0437\u0430\u043c\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u0432 smoke** (\u043d\u0435 \u043f\u0440\u0435\u0434\u043f\u043e\u043b\u0430\u0433\u0430\u0435\u0442\u0441\u044f \u0437\u0430\u0440\u0430\u043d\u0435\u0435). Wall-clock \u2248 T_total / 224 (runs \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b \u2192 embarrassingly parallel, 1 \u043f\u0440\u043e\u0446\u0435\u0441\u0441 \u043d\u0430 run).\n\n| \u0422\u0438\u0440 | \u042f\u0447\u0435\u0439\u043a\u0438 (N_cells) | R | \u0421\u043e\u0441\u0442\u0430\u0432 | \u041d\u0430\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 |\n|---|---|---|---|---|\n| **Smoke** | 3: \u043e\u0441\u043d\u043e\u0432\u043d\u0430\u044f (n=10, L=1, p=0.1, m=2000, \u041b\u0430\u043f\u043b\u0430\u0441), C1 (L=0, \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u043e\u0435 \u0442\u043e \u0436\u0435), C2 (\u0413\u0430\u0443\u0441\u0441, \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u043e\u0435 \u0442\u043e \u0436\u0435) | 5 | CAMUV + FCMP + LiNGAM | \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d\u0430; **\u0437\u0430\u043c\u0435\u0440 t_X** \u0434\u043b\u044f \u0440\u0430\u0441\u0447\u0451\u0442\u0430 \u0431\u044e\u0434\u0436\u0435\u0442\u0430 |\n| **\u042f\u0434\u0440\u043e** | 24: n\u2208{10,20,50} \u00d7 L\u2208{0,1,2,3} \u00d7 m\u2208{1000,5000}, p=0.15, \u041b\u0430\u043f\u043b\u0430\u0441 (L=0 = C1); +3 C2 (n=20, L\u2208{1,2,3}, m=5000, \u0413\u0430\u0443\u0441\u0441) \u2192 27 | 20 | \u0432\u0441\u0435 5 \u043c\u0435\u0442\u043e\u0434\u043e\u0432 + Random | H1, H2 |\n| **\u0420\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u043d\u044b\u0439** | \u0434\u043e 216: \u00d7 p\u2208{0.05,0.1,0.2} \u00d7 m\u2208{500,2000,10000} \u00d7 \u0448\u0443\u043c\u2208{\u041b\u0430\u043f\u043b\u0430\u0441, exp-Gauss}; + C3 (1 \u044f\u0447\u0435\u0439\u043a\u0430) | 100 | \u0432\u0441\u0435 \u043c\u0435\u0442\u043e\u0434\u044b | \u043f\u043e\u043b\u043d\u0430\u044f \u043a\u0430\u0440\u0442\u0430 \u0443\u0441\u043b\u043e\u0432\u0438\u0439; \u0443\u0440\u0435\u0437\u0430\u0435\u0442\u0441\u044f \u0444\u043e\u0440\u043c\u0443\u043b\u043e\u0439 T_total \u043f\u043e\u0434 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0439 \u0431\u044e\u0434\u0436\u0435\u0442 (\u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u0440\u0435\u0436\u0435\u043c R, \u043f\u043e\u0442\u043e\u043c p/m) |\n| **\u0420\u0435\u0430\u043b\u044c\u043d\u044b\u0435** | Sachs \u00d7 5 \u043c\u0435\u0442\u043e\u0434\u043e\u0432 (1 run; \u043e\u043f\u0446. subsampling \u00d7100) | 1/100 | \u0432\u0441\u0435 \u043c\u0435\u0442\u043e\u0434\u044b | H3 |\n\n\u041f\u043e\u0441\u043b\u0435 smoke: \u043f\u043e\u0434\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u043c \u0437\u0430\u043c\u0435\u0440\u044b t_X \u0432 \u0444\u043e\u0440\u043c\u0443\u043b\u0443 \u2192 \u043f\u043e\u043b\u0443\u0447\u0430\u0435\u043c \u0442\u043e\u0447\u043d\u044b\u0439 \u0431\u044e\u0434\u0436\u0435\u0442 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0442\u0438\u0440\u0430; \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c \u0432\u044b\u0431\u0438\u0440\u0430\u0435\u0442 \u0442\u0438\u0440 \u043f\u043e\u0434 \u0440\u0430\u0441\u043a\u0440\u044b\u0442\u044b\u0439 \u0431\u044e\u0434\u0436\u0435\u0442. \u041e\u0446\u0435\u043d\u043a\u0430 \u043f\u043e\u0440\u044f\u0434\u043a\u0430 \u0432\u0435\u043b\u0438\u0447\u0438\u043d t_X (\u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440, \u041d\u0415 \u0444\u0430\u043a\u0442, \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442\u0441\u044f smoke): LiNGAM/FCMP \u043f\u0440\u0438 n\u226450, m\u226410000 \u2014 \u0441\u0435\u043a\u0443\u043d\u0434\u044b..\u043c\u0438\u043d\u0443\u0442\u044b \u043d\u0430 CPU; CAMUV \u2014 \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e \u0434\u043e \u0437\u0430\u043c\u0435\u0440\u0430 (\u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 A3/A6; \u0435\u0441\u043b\u0438 NN-\u043c\u0435\u0442\u043e\u0434 \u2014 \u043c\u0438\u043d\u0443\u0442\u044b, \u0442\u043e\u0433\u0434\u0430 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u043d\u044b\u0439 \u0442\u0438\u0440 \u043c\u043e\u0436\u0435\u0442 \u0443\u043f\u0435\u0440\u0435\u0442\u044c\u0441\u044f \u0432 CPU-\u0431\u044e\u0434\u0436\u0435\u0442).\n\n### \u0422\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u044f \u043a \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u044e (\u043d\u0430 \u043c\u043e\u043c\u0435\u043d\u0442 \u0437\u0430\u043f\u0443\u0441\u043a\u0430, \u0441\u0435\u0439\u0447\u0430\u0441 \u043d\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043c\u044b \u2014 \u0441\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430)\n- Python **3.10\u20133.12** (\u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043e\u0431\u0440\u0430\u0437): \u0442\u0435\u043a\u0443\u0449\u0438\u0439 3.14 \u2014 \u0440\u0438\u0441\u043a \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u044f wheels \u0434\u043b\u044f causal-learn-\u0441\u0442\u044d\u043a\u0430 [\u041e\u0426\u0415\u041d\u041a\u0410 \u0420\u0418\u0421\u041a\u0410].\n- \u041f\u0430\u043a\u0435\u0442\u044b: numpy, pandas, scipy, scikit-learn, networkx, causal-learn, matplotlib, pytest; ICU-LiNGAM (pip/git); CAMUV (git) \u043b\u0438\u0431\u043e \u0440\u0435\u0438\u043c\u043f\u043b\u0435\u043c\u0435\u043d\u0442 (\u00a78).\n- \u0421\u0435\u0442\u044c \u043d\u0430 \u043c\u043e\u043c\u0435\u043d\u0442 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0438 + \u0441\u043a\u0430\u0447\u0438\u0432\u0430\u043d\u0438\u044f Sachs (\u0438\u043b\u0438 pre-baked \u043e\u0431\u0440\u0430\u0437 \u0441 \u043f\u0430\u043a\u0435\u0442\u0430\u043c\u0438 \u0438 \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u043e\u043c).\n- CPU: 224 \u044f\u0434\u0440\u0430 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e; \u043f\u0430\u043c\u044f\u0442\u044c: \u043f\u0440\u0435\u0434\u043f\u043e\u043b\u043e\u0436\u0438\u0442\u0435\u043b\u044c\u043d\u043e <4 GB \u043d\u0430 run \u0432 \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u0430\u0445 \u044f\u0434\u0440\u0430 [\u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u0415, \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u0432 smoke].\n- \u0412\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u044c: \u0441\u0438\u0434\u044b = hash(\u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438), \u0437\u0430\u043a\u0440\u0435\u043f\u043b\u0451\u043d\u043d\u044b\u0435 \u0432\u0435\u0440\u0441\u0438\u0438 \u043f\u0430\u043a\u0435\u0442\u043e\u0432, YAML-\u043a\u043e\u043d\u0444\u0438\u0433 \u043a\u0430\u0436\u0434\u043e\u0433\u043e run, \u0430\u0440\u0445\u0438\u0432\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u0432\u044b\u0445\u043e\u0434\u043e\u0432.\n\n## 8. Fallback: \u0440\u0435\u0438\u043c\u043f\u043b\u0435\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u044f CAMUV (\u0435\u0441\u043b\u0438 A3 \u043b\u043e\u0436\u043d\u043e \u2014 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u043d\u0435\u0442, \u0441\u0435\u0442\u044c \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0430)\n\u041e\u0442\u0434\u0435\u043b\u044c\u043d\u0430\u044f \u0440\u0430\u0431\u043e\u0447\u0430\u044f \u0437\u0430\u0434\u0430\u0447\u0430, **\u043e\u0446\u0435\u043d\u043a\u0430 \u043e\u0431\u044a\u0451\u043c\u0430 \u2014 \u043e\u0446\u0435\u043d\u043a\u0430, \u043d\u0435 \u0444\u0430\u043a\u0442**:\n1. \u0420\u0430\u0437\u0431\u043e\u0440 \u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c\u0430 \u043f\u043e \u0441\u0442\u0430\u0442\u044c\u0435: \u043f\u0440\u0435\u0434\u043f\u043e\u0441\u044b\u043b\u043a\u0438, \u0446\u0435\u043b\u0435\u0432\u0430\u044f \u0444\u0443\u043d\u043a\u0446\u0438\u044f, \u0438\u043d\u0438\u0446\u0438\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f, \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0438 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0438, \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0430 \u0433\u0440\u0430\u043d\u0438\u0446 \u2014 1\u20132 \u0434\u043d\u044f.\n2. \u0420\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f: \u043c\u043e\u0434\u0435\u043b\u044c \u0434\u0430\u043d\u043d\u044b\u0445 + \u044d\u0441\u0442\u0438\u043c\u0430\u0442\u043e\u0440 + unit-\u0442\u0435\u0441\u0442\u044b (\u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0442\u0435\u0441\u0442\u044b \u043d\u0430 toy-\u043f\u0440\u0438\u043c\u0435\u0440\u0430\u0445 \u0438\u0437 \u0441\u0442\u0430\u0442\u044c\u0438, \u0435\u0441\u043b\u0438 \u0435\u0441\u0442\u044c) \u2014 1\u20132 \u043d\u0435\u0434\u0435\u043b\u0438 \u0438\u043d\u0436\u0435\u043d\u0435\u0440\u043d\u043e\u0433\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438.\n3. \u0412\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f: \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u0435\u0434\u0435\u043d\u0438\u0435 \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u0432 \u0441\u0442\u0430\u0442\u044c\u0435 \u0447\u0438\u0441\u0435\u043b \u043d\u0430 1\u20132 \u0435\u0451 \u0441\u0438\u043d\u0442\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0430\u0445 \u2014 1 \u043d\u0435\u0434\u0435\u043b\u044f.\n4. \u0418\u043d\u0442\u0435\u0433\u0440\u0430\u0446\u0438\u044f \u0432 \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d + \u043f\u043e\u043c\u0435\u0442\u043a\u0430 \u0432\u043e \u0432\u0441\u0435\u0445 \u043e\u0442\u0447\u0451\u0442\u0430\u0445 \u00ab\u0440\u0435\u0438\u043c\u043f\u043b\u0435\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u044f, \u043d\u0435 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u043a\u043e\u0434\u00bb.\n\u0420\u0438\u0441\u043a: \u043d\u0435\u043f\u043e\u043b\u043d\u043e\u0442\u0430 \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u044f \u0432 \u0441\u0442\u0430\u0442\u044c\u0435 (\u043d\u0435\u0434\u043e\u0441\u0442\u0430\u044e\u0449\u0438\u0435 \u0434\u0435\u0442\u0430\u043b\u0438 \u0433\u0438\u043f\u0435\u0440\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432) \u2192 \u043c\u0438\u0442\u0438\u0433\u0446\u0438\u044f: \u0437\u0430\u043f\u0440\u043e\u0441 \u0430\u0432\u0442\u043e\u0440\u0430\u043c; \u043f\u0440\u0438 \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u0438 \u2014 \u0443\u043c\u0435\u043d\u044c\u0448\u0435\u043d\u0438\u0435 scope \u0432\u044b\u0432\u043e\u0434\u043e\u0432. \u0415\u0441\u043b\u0438 \u0440\u0435\u0438\u043c\u043f\u043b\u0435\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u044f \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u0430 (\u043d\u0438 \u043a\u043e\u0434, \u043d\u0438 \u0441\u0435\u0442\u044c, \u043d\u0438 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e\u0435 \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u0435): \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u0434\u0435\u0433\u0440\u0430\u0434\u0438\u0440\u0443\u0435\u0442 \u0434\u043e \u00ab\u0431\u0430\u0437\u043b\u0430\u0439\u043d\u043e\u0432\u043e\u0433\u043e \u043f\u0438\u043b\u043e\u0442\u0430\u00bb (FCMP vs ICU-LiNGAM vs LiNGAM vs Random) \u2014 \u0445\u0430\u0440\u0430\u043a\u0442\u0435\u0440\u0438\u0437\u0443\u0435\u0442 \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u0443 \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u043d\u0433\u0430, \u043d\u043e **\u043d\u0435 \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442** \u043d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441 \u043f\u0440\u043e CAMUV; \u043f\u043e\u043c\u0435\u0447\u0430\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u0447\u0430\u0441\u0442\u0438\u0447\u043d\u044b\u0439 \u043e\u0442\u0432\u0435\u0442.\n\n## 9. \u041f\u043e\u0440\u044f\u0434\u043e\u043a \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f (\u0444\u0430\u0437\u044b \u0441 gates)\n- **\u0424\u0430\u0437\u0430 0 (gate):** \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f A1\u2013A5 (\u0443\u0442\u043e\u0447\u043d\u0435\u043d\u0438\u044f \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044f \u043f\u043e \u0442\u0435\u043c\u0430\u043c 1\u20133, 5 + \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0435\u0432 \u043f\u0440\u0438 \u043d\u0430\u043b\u0438\u0447\u0438\u0438 \u0441\u0435\u0442\u0438). \u0411\u0435\u0437 A1\u2013A3 \u0441\u0442\u0430\u0440\u0442 \u0437\u0430\u043f\u0440\u0435\u0449\u0451\u043d.\n- **\u0424\u0430\u0437\u0430 1:** \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0435 (\u043e\u0431\u0440\u0430\u0437 3.10\u20133.12), \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430, unit-\u0442\u0435\u0441\u0442\u044b \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440\u0430 (\u00a73.1), \u0437\u0430\u0445\u0432\u0430\u0442 Sachs (A5).\n- **\u0424\u0430\u0437\u0430 2:** smoke \u2014 \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d\u0430, \u0437\u0430\u043c\u0435\u0440 t_X, \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 A6.\n- **\u0424\u0430\u0437\u0430 3:** \u044f\u0434\u0440\u043e (27 \u044f\u0447\u0435\u0435\u043a, R=20) \u2192 H1, H2.\n- **\u0424\u0430\u0437\u0430 4:** \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u043d\u044b\u0439 (\u043f\u043e \u0444\u043e\u0440\u043c\u0443\u043b\u0435 \u0431\u044e\u0434\u0436\u0435\u0442\u0430) + C3 + Sachs \u2192 \u043a\u0430\u0440\u0442\u0430 \u0443\u0441\u043b\u043e\u0432\u0438\u0439, H3.\n- **\u0424\u0430\u0437\u0430 5:** \u0430\u043d\u0430\u043b\u0438\u0437 \u043f\u043e \u00a76, \u043e\u0442\u0447\u0451\u0442 \u0441 \u044f\u0432\u043d\u043e\u0439 \u043f\u043e\u043c\u0435\u0442\u043a\u043e\u0439 \u0444\u0430\u043a\u0442\u043e\u0432/\u043e\u0446\u0435\u043d\u043e\u043a/\u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0439.\n\n### \u041a\u043b\u044e\u0447\u0435\u0432\u044b\u0435 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f (\u0438\u0442\u043e\u0433\u043e\u0432\u044b\u0439 \u0441\u043f\u0438\u0441\u043e\u043a, \u0432\u0441\u0451 \u0438\u0437 \u00a72)\n[\u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u0415] A1 (\u043c\u043e\u0434\u0435\u043b\u044c CAMUV: \u043b\u0438\u043d\u0435\u0439\u043d\u043e\u0441\u0442\u044c, \u043d\u0435\u0433\u0430\u0443\u0441\u0441\u043e\u0432\u043e\u0441\u0442\u044c, \u0442\u043e\u043b\u044c\u043a\u043e \u043e\u0431\u0449\u0438\u0435 \u043f\u0440\u0438\u0447\u0438\u043d\u044b, \u043d\u0435\u0442 \u043a\u043e\u043b\u043b\u0430\u0439\u0434\u0435\u0440\u043e\u0432, \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e K_max) \u00b7 [\u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u0415] A2 (\u0432\u044b\u0445\u043e\u0434 = \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0433\u0440\u0430\u0444) \u00b7 [\u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u0415] A3 (\u043f\u0443\u0431\u043b\u0438\u0447\u043d\u0430\u044f \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f) \u00b7 [\u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u0415] A4 (\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u044c \u0431\u0430\u0437\u043b\u0430\u0439\u043d\u043e\u0432) \u00b7 [\u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u0415] A5 (\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u044c Sachs) \u00b7 [\u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u0415] A6 (CPU-\u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043c\u043e\u0441\u0442\u044c) \u00b7 [\u041e\u0426\u0415\u041d\u041a\u0410] \u043e\u0431\u044a\u0451\u043c \u0440\u0435\u0438\u043c\u043f\u043b\u0435\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u0438 \u00a78 \u00b7 [\u041e\u0426\u0415\u041d\u041a\u0410] \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0432\u0435\u043b\u0438\u0447\u0438\u043d t_X \u0432 \u00a77. \u0412\u0441\u0451 \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u043e\u0435 (\u0441\u043e\u0441\u0442\u0430\u0432 workspace, \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u0441\u0440\u0435\u0434\u044b) \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u043d\u044b\u0435 \u0444\u0430\u043a\u0442\u044b."}", "origin": "completion"}, "llm_response_id": "chatcmpl-bb6f94a52674487db0c403f8a39fcb03", "security_risk": "UNKNOWN", "critic_result": null, "summary": "Full final experiment design with assumptions, staged budget, fallback", "kind": "ActionEvent"}
